// ---------- Chicago along the tracks (scrolling tiles) ----------
const TILE = 320, SPEED = 14, GROUND = -1.25;
function building(p, x, z, w, d, h, kind, seed) { const r = rng(seed); let mat;
  if (kind === 'brick') { const bt = brickTex(['#8a4a32', '#9a5a3a', '#7a3a2a', '#a8684a'][Math.floor(r() * 4)], seed); bt.repeat.set(w / 3, h / 3); mat = SM('#ffffff', { map: bt, roughness: 0.9 }); }
  else { mat = SM(['#b8b4a8', '#8a8a86', '#c8c0b0'][Math.floor(r() * 3)], { roughness: 0.8 }); }
  const b = add(p, Bx(w, h, d), mat, x, GROUND + h / 2, z); const wt = windowsTex(Math.max(2, Math.round(w / 2.5)), Math.max(2, Math.round(h / 3)), 0.12, 'rgba(0,0,0,0)', '#2a3440', seed + 1); const wm = new T3.MeshStandardMaterial({ map: wt, transparent: true, roughness: 0.3, metalness: 0.3 });
  for (const sx of [-1, 1]) add(p, new T3.PlaneGeometry(d * 0.9, h * 0.85), wm, x + sx * (w / 2 + 0.02), GROUND + h * 0.5, z, false).rotation.y = sx * PI / 2;
  add(p, Bx(w + 0.3, 0.3, d + 0.3), SM('#5a5a58'), x, GROUND + h + 0.15, z); if (kind === 'brick' && r() < 0.35) { const tw = new T3.Group(); tw.position.set(x + (r() - 0.5) * w * 0.4, GROUND + h, z); p.add(tw); for (const [dx, dz] of [[-0.8, -0.8], [0.8, -0.8], [-0.8, 0.8], [0.8, 0.8]]) add(tw, Cy(0.07, 0.07, 3, 8), SM('#3a3a3a'), dx, 1.5, dz); add(tw, Cy(1.3, 1.3, 2.4, 16), SM('#6a4a30', { roughness: 0.9 }), 0, 4.1, 0); add(tw, new T3.ConeGeometry(1.4, 0.9, 16), SM('#4a3a2a'), 0, 5.75, 0); } }
function tree(p, x, z, s, seed) { const r = rng(seed); add(p, Cy(0.12 * s, 0.18 * s, 2.4 * s, 10), SM('#5a4030', { roughness: 1 }), x, GROUND + 1.2 * s, z); const col = ['#3a6a2a', '#4a7a32', '#2e5a26', '#5a8a3a'][Math.floor(r() * 4)]; for (let k = 0; k < 5; k++) add(p, Sp((1.0 + r() * 0.6) * s, 14, 10), SM(col, { roughness: 0.95 }), x + (r() - 0.5) * 1.2 * s, GROUND + (2.6 + r() * 1.4) * s, z + (r() - 0.5) * 1.2 * s); }
function bush(p, x, z, s, seed) { const r = rng(seed); for (let k = 0; k < 3; k++) add(p, Sp((0.5 + r() * 0.4) * s, 12, 8), SM(['#3a5a2a', '#4a6a30'][k % 2], { roughness: 1 }), x + (r() - 0.5) * s, GROUND + 0.35 * s, z + (r() - 0.5) * s).scale.y = 0.75; }
const CARCOL = ['#c83a2a', '#e8e8ec', '#2a2a30', '#3a5a8a', '#8a8a90', '#d8c8a0'];
function car(p, x, z, rot, seed) { const r = rng(seed); const g = new T3.Group(); g.position.set(x, GROUND, z); g.rotation.y = rot; p.add(g); const col = CARCOL[Math.floor(r() * CARCOL.length)]; const paint = SM(col, { metalness: 0.6, roughness: 0.3 }); add(g, RB(1.8, 0.7, 4.4, 0.15), paint, 0, 0.6, 0); add(g, RB(1.6, 0.6, 2.4, 0.2), paint, 0, 1.15, -0.2); add(g, RB(1.62, 0.45, 2.2, 0.15), SM('#1a2430', { metalness: 0.4, roughness: 0.1 }), 0, 1.18, -0.2); for (const [wx, wz] of [[-0.85, 1.4], [0.85, 1.4], [-0.85, -1.4], [0.85, -1.4]]) add(g, Cy(0.33, 0.33, 0.22, 18), SM('#151515', { roughness: 0.7 }), wx, 0.33, wz).rotation.z = PI / 2; return g; }
function streetLight(p, x, z, side) { add(p, Cy(0.06, 0.09, 7, 10), SM('#4a4e54', { metalness: 0.6 }), x, GROUND + 3.5, z); const arm = add(p, Bx(1.6, 0.08, 0.08), SM('#4a4e54', { metalness: 0.6 }), x + side * 0.8, GROUND + 7, z); add(p, RB(0.5, 0.15, 0.25, 0.05), SM('#d8d8d0'), x + side * 1.5, GROUND + 6.92, z); }
function pole(p, x, z) { add(p, Cy(0.11, 0.14, 10, 10), SM('#6a5038', { roughness: 1 }), x, GROUND + 5, z); add(p, Bx(2.4, 0.12, 0.12), SM('#6a5038'), x, GROUND + 9.3, z); }
function buildTile(p, z0, seed) { const g = new T3.Group(); g.position.z = z0; p.add(g); const r = rng(seed);
  // ground strips: gravel by the tracks, grass verge, road, sidewalk
  add(g, Bx(14, 0.1, TILE), SM('#ffffff', { map: noiseTex(256, 256, '#7a7468', [['rgba(255,255,255,0.12)', 2500, 2], ['rgba(0,0,0,0.18)', 2500, 2]], seed, [4, 80]) }), 1.5, GROUND - 0.05, 0);
  add(g, Bx(10, 0.1, TILE), SM('#ffffff', { map: noiseTex(256, 256, '#5a7a3a', [['rgba(255,255,200,0.08)', 2000, 2], ['rgba(0,40,0,0.18)', 2000, 2]], seed + 1, [6, 100]) }), -10.5, GROUND - 0.04, 0); add(g, Bx(12, 0.1, TILE), SM('#ffffff', { map: noiseTex(256, 256, '#5a7a3a', [['rgba(255,255,200,0.08)', 2000, 2]], seed + 2, [6, 100]) }), 14.5, GROUND - 0.04, 0);
  const asph = SM('#ffffff', { map: noiseTex(256, 256, '#3a3a3e', [['rgba(255,255,255,0.05)', 2000, 2]], seed + 3, [4, 60]), roughness: 0.85 }); add(g, Bx(10, 0.1, TILE), asph, -20.5, GROUND - 0.03, 0); add(g, Bx(0.15, 0.02, TILE), BM('#e8d84a'), -20.5, GROUND + 0.03, 0, false); add(g, Bx(3, 0.25, TILE), SM('#a8a49a'), -27, GROUND + 0.05, 0);
  for (let zz = -TILE / 2 + 10; zz < TILE / 2; zz += 40) pole(g, -6.5, zz + (r() - 0.5) * 6); for (let zz = -TILE / 2 + 5; zz < TILE / 2; zz += 30) streetLight(g, -15.2, zz, -1);
  add(g, Bx(0.04, 1.8, TILE), new T3.MeshStandardMaterial({ color: '#9a9ea4', metalness: 0.6, roughness: 0.4, transparent: true, opacity: 0.35 }), -5, GROUND + 0.9, 0, false); for (let zz = -TILE / 2; zz < TILE / 2; zz += 3) add(g, Cy(0.03, 0.03, 1.9, 6), SM('#7a7e84', { metalness: 0.6 }), -5, GROUND + 0.95, zz);
  for (let i = 0; i < 40; i++) { const zz = -TILE / 2 + r() * TILE; if (r() < 0.6) tree(g, -8 - r() * 4, zz, 0.8 + r() * 0.6, seed * 100 + i); else bush(g, -6 - r() * 4, zz, 1 + r(), seed * 100 + i); }
  for (let i = 0; i < 30; i++) { const zz = -TILE / 2 + r() * TILE; if (r() < 0.5) tree(g, 9 + r() * 5, zz, 0.8 + r() * 0.7, seed * 200 + i); else bush(g, 8 + r() * 3, zz, 1 + r(), seed * 200 + i); }
  for (let zz = -TILE / 2 + 6; zz < TILE / 2; zz += 9 + r() * 14) car(g, -23.2 + (r() < 0.5 ? 0 : 5.5), zz, r() < 0.5 ? 0 : PI, seed * 300 + zz);
  let zz = -TILE / 2; while (zz < TILE / 2) { const w = 10 + r() * 14, h = 7 + r() * (r() < 0.2 ? 30 : 12); building(g, -36 - w / 2 + 4, zz + w / 2, w * 0.9, 10 + r() * 6, h, r() < 0.65 ? 'brick' : 'stone', seed * 400 + Math.floor(zz)); zz += w + 2 + r() * 5; }
  zz = -TILE / 2; while (zz < TILE / 2) { const w = 14 + r() * 20, h = 6 + r() * 14; building(g, 24 + w * 0.3, zz + w / 2, 12 + r() * 6, w * 0.9, h, r() < 0.7 ? 'brick' : 'stone', seed * 500 + Math.floor(zz)); zz += w + 4 + r() * 10; }
  return g; }
function tracks(p, x) { const g = new T3.Group(); g.position.x = x; p.add(g); const steel = SM('#8a8a8e', { metalness: 0.9, roughness: 0.35 }); for (const sx of [-0.72, 0.72]) add(g, Bx(0.08, 0.16, 3000), steel, sx, GROUND + 0.3, -600); const tie = SM('#4a3a2a', { roughness: 1 }); R.ties = R.ties || []; const ties = new T3.InstancedMesh(Bx(2.6, 0.14, 0.24), tie, 1200); const M = new T3.Matrix4(); for (let i = 0; i < 1200; i++) { M.makeTranslation(0, GROUND + 0.15, -900 + i * 0.6 + 450); ties.setMatrixAt(i, M); } ties.receiveShadow = true; g.add(ties); R.ties.push(ties); add(g, Bx(3.6, 0.2, 3000), SM('#6a6458', { roughness: 1 }), 0, GROUND + 0.02, -600, false); return g; }
function skyline(p) { const g = R.skyline = new T3.Group(); p.add(g); g.position.set(-80, 0, -1300);
  const dark = SM('#ffffff', { map: towerTex('#1e2228', '#2e343c', 1), roughness: 0.3, metalness: 0.6 });
  // Willis Tower: bundled tubes, two antennas
  const wt = new T3.Group(); wt.position.set(0, GROUND, 0); g.add(wt); const hs = [[270, 270, 330], [330, 442, 330], [270, 400, 270]]; for (let i = 0; i < 3; i++) for (let j = 0; j < 3; j++) { const h = hs[i][j] * 0.9; add(wt, Bx(22, h, 22), dark, (i - 1) * 23, h / 2, (j - 1) * 23); } for (const dx of [-6, 6]) add(wt, Cy(0.9, 1.4, 90, 8), SM('#e8e8e8'), dx, 442 * 0.9 + 45, 0);
  // John Hancock: tapered, X-braced, two antennas
  const jh = new T3.Group(); jh.position.set(180, GROUND, 220); g.add(jh); const xb = ctex(128, 512, (c, w, h) => { c.fillStyle = '#1a1c20'; c.fillRect(0, 0, w, h); c.strokeStyle = '#3a3e44'; c.lineWidth = 5; for (let y = 0; y < h; y += 64) { c.beginPath(); c.moveTo(0, y); c.lineTo(w, y + 64); c.moveTo(w, y); c.lineTo(0, y + 64); c.stroke(); } }); add(jh, new T3.CylinderGeometry(22, 34, 310, 4), SM('#ffffff', { map: xb, roughness: 0.4, metalness: 0.5 }), 0, 155, 0).rotation.y = PI / 4; for (const dx of [-6, 6]) add(jh, Cy(0.9, 1.3, 80, 8), SM('#e8e8e8'), dx, 350, 0);
  // Trump Tower (silver, stepped, spire) + Aon (white) + filler towers
  const silver = SM('#ffffff', { map: towerTex('#a8b8c8', '#c8d4e0', 3), metalness: 0.8, roughness: 0.15 }); const tt = new T3.Group(); tt.position.set(110, GROUND, 140); g.add(tt); [[34, 120], [28, 220], [22, 300], [16, 345]].forEach(([w, h], i) => add(tt, Bx(w, h, w * 0.6), silver, 0, h / 2, 0)); add(tt, Cy(0.6, 1.5, 70, 8), SM('#d8d8d8'), 0, 380, 0);
  add(g, Bx(40, 340, 40), SM('#ffffff', { map: towerTex('#e8e8e4', '#c8c8c4', 5), roughness: 0.5 }), 240, GROUND + 170, 120);
  const r = rng(77); for (let i = 0; i < 70; i++) { const x = -260 + r() * 640, z = -120 + r() * 360, w = 18 + r() * 26, h = 50 + r() * 190; if (Math.hypot(x, z) < 45) continue; add(g, Bx(w, h, w * (0.7 + r() * 0.5)), SM('#ffffff', { map: towerTex(['#4a5260', '#6a6e74', '#8a8e92', '#3a4048', '#a8a49a'][Math.floor(r() * 5)], '#2a2e34', i), roughness: 0.4, metalness: 0.4 }), x, GROUND + h / 2, z, false); } }
function buildWorld() { const w = R.world = new T3.Group(); scene.add(w); tracks(w, 0); tracks(w, 4.6); R.scroll = new T3.Group(); w.add(R.scroll); R.tiles = [0, 1, 2, 3].map(i => buildTile(R.scroll, -TILE * 1.5 + i * TILE, 11 + i)); skyline(w);
  add(w, Bx(6000, 0.1, 6000), SM('#5a6a4a', { roughness: 1 }), 0, GROUND - 0.12, 0, false);
  // the other train (passes on track 2)
  const ot = R.other = new T3.Group(); ot.position.set(4.6, 0, 0); w.add(ot); for (let k = 0; k < 6; k++) { const car_ = new T3.Group(); car_.position.z = k * 17.5; ot.add(car_); if (k === 0) { add(car_, RB(3.0, 3.5, 17, 0.3), SM('#c8a02a', { metalness: 0.4, roughness: 0.5 }), 0, 1.2, 0); add(car_, Bx(3.02, 0.4, 17), SM('#2a2a2a'), 0, 0.3, 0); R.otHead = spr(car_, GLOW, '#fff6d8', 1.6, 0, 1.0, -8.7, 0.9); } else { add(car_, Bx(3.0, 3.2, 16.5), SM(['#7a3a2a', '#5a5a5e', '#8a4a2a'][k % 3], { roughness: 0.8, metalness: 0.3 }), 0, 1.0, 0); add(car_, Bx(3.02, 0.18, 16.5), SM('#2a2a2a'), 0, 2.6, 0); } for (const zz of [-6, 6]) add(car_, Cy(0.45, 0.45, 3.1, 18), SM('#1a1a1a', { metalness: 0.6 }), 0, -0.75, zz).rotation.z = PI / 2; }
}

