  if (mode === 'face') { const g = c.createLinearGradient(0, 0, 0, h); g.addColorStop(0, '#3a5068'); g.addColorStop(1, '#1a2838'); c.fillStyle = g; c.fillRect(0, 0, w, h); c.fillStyle = '#2a3a4a'; c.beginPath(); c.ellipse(160, 210, 80, 60, 0, 0, 7); c.fill(); c.fillStyle = '#e4bca0'; c.fillRect(146, 118, 28, 30); c.beginPath(); c.ellipse(160, 92, 36, 46, 0, 0, 7); c.fill(); c.fillStyle = '#c8a070'; c.beginPath(); c.ellipse(160, 66, 40, 30, 0, PI, 0); c.fill(); c.beginPath(); c.ellipse(132, 100, 12, 34, 0.1, 0, 7); c.fill(); c.beginPath(); c.ellipse(188, 100, 12, 34, -0.1, 0, 7); c.fill(); c.fillStyle = '#2a2a3a'; c.fillRect(144, 88, 10, 4); c.fillRect(166, 88, 10, 4); c.fillStyle = '#a05a50'; c.fillRect(152, 114, 16, 2 + Math.abs(Math.sin(T * 12)) * 4); c.fillStyle = '#8ac8ff'; c.font = '13px Russo'; c.fillText('CAPT. GOODWIN', 10, 190); }
  if (mode === 'mission') { c.fillStyle = '#ff5a4a'; c.font = '26px Russo'; c.textAlign = 'center'; c.fillText('FIND THE BOMBER', 160, 38); c.fillStyle = '#5a8ab8'; for (let k = 0; k < 20; k++) { const bh = 20 + ((k * 13) % 7) * 11; c.fillRect(14 + k * 15, 170 - bh, 11, bh); } c.fillStyle = '#fff'; c.font = '16px Russo'; c.fillText('NEXT TARGET . CHICAGO', 160, 194); c.textAlign = 'left'; if (Math.floor(T * 3) % 2) { c.strokeStyle = '#ff3a2a'; c.lineWidth = 3; c.beginPath(); c.arc(160, 120, 42, 0, 7); c.stroke(); } }
  if (mode === 'wipe') { c.fillStyle = '#1a0606'; c.fillRect(0, 0, w, h); c.fillStyle = '#ff3a2a'; c.font = '26px Russo'; c.textAlign = 'center'; c.fillText('MEMORY WIPE', 160, 86); c.fillStyle = '#fff'; c.fillRect(40, 116, 240, 16); c.fillStyle = '#ff3a2a'; c.fillRect(42, 118, 236 * ((T * 0.3) % 1), 12); c.textAlign = 'left'; }
  if (mode === 'glitch') { const r = rng(Math.floor(T * 20)); for (let k = 0; k < 30; k++) { c.fillStyle = ['#ff3a6a', '#3affea', '#ffffff', '#06121c'][Math.floor(r() * 4)]; c.fillRect(r() * w, r() * h, r() * 140, 2 + r() * 10); } }
