  add(g, RB(1.4, 0.9, 2.6, 0.35), SM('#7a828c', { metalness: 0.8, roughness: 0.35 }), 0, 0.75, -0.8); add(g, RB(1.0, 0.1, 1.6, 0.05), new T3.MeshStandardMaterial({ color: '#8ac8e8', transparent: true, opacity: 0.6, emissive: '#2a6a8a', emissiveIntensity: 0.6, roughness: 0.1 }), 0, 1.22, -0.8); R.podGlow = spr(g, GLOW, '#8ad8ff', 2.4, 0, 1.3, -0.8, 0.4);
